const b = $json.body,
  server = "YOUR_SERVER_DOMAIN",
  engine = "https://YOUR_DOCKER_GATEWAY";
if (
  b.server_domain !== server ||
  b.command !== "dependent_containers_information_stats" ||
  !/^[a-zA-Z0-9][a-zA-Z0-9_.-]{0,200}$/.test(b.domain)
)
  throw Error("Invalid request");
let base = engine.replace(/\/$/, "") + "/v1.44/containers/",
  p = { domain: b.domain };
for (const suffix of ["ml", "db", "redis"]) {
  let root = base + encodeURIComponent(b.domain + "_" + suffix);
  p[suffix + "Inspect"] = root + "/json";
  p[suffix + "Stats"] = root + "/stats?stream=false";
}
return { json: p, pairedItem: { item: $itemIndex } };

function stats({
  domain,
  imStatus,
  imBody,
  smStatus,
  smBody,
  idStatus,
  idBody,
  sdStatus,
  sdBody,
  irStatus,
  irBody,
  srStatus,
  srBody,
}) {
  const size = (v, base, units, p) => {
      v = Number(v) || 0;
      let i = 0;
      while (v >= base && i < units.length - 1) {
        v /= base;
        i++;
      }
      return Number(v.toPrecision(p)).toString() + units[i];
    },
    dec = (v) => size(v, 1000, ["B", "kB", "MB", "GB", "TB", "PB"], 3),
    bin = (v) => size(v, 1024, ["B", "KiB", "MiB", "GiB", "TiB", "PiB"], 4),
    pct = (v) => (Number(v) || 0).toFixed(2) + "%";
  const fmt = (ins, stat, suffix) => {
    if (ins.status === 404) return { inspect: {}, stats: {} };
    if (ins.status !== 200 || !ins.body || typeof ins.body !== "object")
      throw Error("Inspect container failed: " + suffix);
    if (stat.status === 404 || stat.status === 409 || stat.status === 500)
      return { inspect: [ins.body], stats: {} };
    if (stat.status !== 200 || !stat.body || typeof stat.body !== "object")
      throw Error("Read container stats failed: " + suffix);
    const s = stat.body,
      c = s.cpu_stats || {},
      p = s.precpu_stats || {},
      u = c.cpu_usage || {},
      pu = p.cpu_usage || {},
      dc = (u.total_usage || 0) - (pu.total_usage || 0),
      ds = (c.system_cpu_usage || 0) - (p.system_cpu_usage || 0),
      cores = c.online_cpus || u.percpu_usage?.length || 0,
      cpu = dc > 0 && ds > 0 ? (dc / ds) * cores * 100 : 0,
      m = s.memory_stats || {},
      mem = m.usage || 0,
      cache = m.stats?.total_inactive_file ?? m.stats?.inactive_file ?? 0,
      used = cache < mem ? mem - cache : mem,
      net = Object.values(s.networks || {}).reduce(
        (a, v) => [a[0] + (v.rx_bytes || 0), a[1] + (v.tx_bytes || 0)],
        [0, 0],
      ),
      blk = (s.blkio_stats?.io_service_bytes_recursive || []).reduce(
        (a, v) => {
          let op = String(v.op || "").toLowerCase();
          if (op.startsWith("r")) a[0] += v.value || 0;
          if (op.startsWith("w")) a[1] += v.value || 0;
          return a;
        },
        [0, 0],
      );
    return {
      inspect: [ins.body],
      stats: {
        BlockIO: dec(blk[0]) + " / " + dec(blk[1]),
        CPUPerc: pct(cpu),
        Container: domain + "_" + suffix,
        ID: String(s.id || "").slice(0, 12),
        MemPerc: pct(m.limit ? (used / m.limit) * 100 : 0),
        MemUsage: bin(used) + " / " + bin(m.limit || 0),
        Name: String(s.name || "").replace(/^\//, "") || "--",
        NetIO: dec(net[0]) + " / " + dec(net[1]),
        PIDs: String(s.pids_stats?.current || 0),
      },
    };
  };
  const a = fmt({ status: imStatus, body: imBody }, { status: smStatus, body: smBody }, "ml"),
    b = fmt({ status: idStatus, body: idBody }, { status: sdStatus, body: sdBody }, "db"),
    c = fmt({ status: irStatus, body: irBody }, { status: srStatus, body: srBody }, "redis");
  return {
    result: {
      status: "success",
      message: "",
      data: {
        inspect_ml: a.inspect,
        stats_ml: a.stats,
        inspect_db: b.inspect,
        stats_db: b.stats,
        inspect_redis: c.inspect,
        stats_redis: c.stats,
      },
    },
  };
}

const p = $("Validate and prepare container URLs").item.json;
const get = (n) => {
  let r = $(n).item.json;
  return { status: r.statusCode, body: r.body };
};
return {
  json: stats({
    domain: p.domain,
    ...Object.fromEntries(
      [
        ["im", "Read mlInspect"],
        ["sm", "Read mlStats"],
        ["id", "Read dbInspect"],
        ["sd", "Read dbStats"],
        ["ir", "Read redisInspect"],
        ["sr", "Read redisStats"],
      ].flatMap(([k, n]) => [
        [k + "Status", get(n).status],
        [k + "Body", get(n).body],
      ]),
    ),
  }).result,
  pairedItem: { item: $itemIndex },
};
